with open('/workspace/outputs/t05_clean_stop_times.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_times.append(row)

# Read trips to get route_ids
trips = {}
with open('/workspace/inputs/gtfs/sample_city_gtfs.zip', 'rb') as f:
    z = zipfile.ZipFile(f, 'r')
    trips = z.namelist()
    for trip in trips:
        if 'trips' in trip:
            trips[trip] = {}
            content = z.read(trip).decode('utf-8')
            # Parse trips.txt
            for line in content.strip().split('\n'):
                if ',' in line:
                    parts = line.split(',')
                    if len(parts) >= 5:
                        trip_id, arrival, departure, stop_id, stop_sequence = parts[0], parts[1], parts[2], parts[3], parts[4]
                        if stop_id and stop_id not in trips[trip]:
                            trips[trip][stop_id] = {'arrival': arrival, 'departure': departure}

# Read stops
stops = {}
with open('/workspace/outputs/t05_clean_stops.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops[row['stop_id']] = row

# Process stop_times to get departures per stop
stop_departures = defaultdict(list)
for row in stop_times:
    stop_id = int(row['stop_id'])
    dep_time = row['departure_time']
    stop_departures[stop_id].append(dep_time)

# Count routes for each stop
stop_routes = defaultdict(set)
for stop_id, dep_times in stop_departures.items():
    for trip_id, stops_in_trip in trips.items():
        if stop_id in stops_in_trip:
            stop_routes[stop_id].add(trip_id)

# Calculate first/last departure
first_departures = {}
last_departures = {}
for stop_id, dep_times in stop_departures.items():
    if dep_times:
        first_departures[stop_id] = min(dep_times)
        last_departures[stop_id] = max(dep_times)

# Write output
with open('/workspace/outputs/t06_stop_service_intensity.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['stop_id', 'stop_name', 'stop_lat', 'stop_lon', 'n_departures', 'n_routes', 'first_departure', 'last_departure'])
    for stop_id, stop in stops.items():
        n_departures = len(stop_departures[stop_id])
        n_routes = len(stop_routes[stop_id])
        first_dep = first_departures[stop_id]
        last_dep = last_departures[stop_id]
        writer.writerow([stop['stop_id'], stop['stop_name'], stop['stop_lat'], stop['stop_lon'], 
                        n_departures, n_routes, first_dep, last_dep])

print(f"Processed {len(stops)} stops")

